package run.ikaros.photo; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException;
@Service public class PersistentPhotoMetadataService implements PhotoMetadataService{private final PhotoRepository photos;public PersistentPhotoMetadataService(PhotoRepository p){photos=p;}@Override public Mono<PhotoView> update(UUID o,UUID id,UpdatePhotoMetadataRequest r){return owned(o,id).flatMap(p->photos.save(new PhotoEntity(p.id(),p.ownerId(),p.resourceId(),r.captureTime(),r.captureTimeLocal(),r.timeZone(),r.width(),r.height(),r.orientation(),r.cameraMake(),r.cameraModel(),r.lensModel(),r.latitude(),r.longitude(),p.version()))).map(this::view);}@Override public Mono<PhotoView> get(UUID o,UUID id){return owned(o,id).map(this::view);}private Mono<PhotoEntity> owned(UUID o,UUID id){return photos.findById(id).filter(p->p.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Photo 不存在或无权访问")));}private PhotoView view(PhotoEntity p){return new PhotoView(p.id(),p.resourceId(),p.captureTime(),p.width(),p.height(),p.cameraMake(),p.cameraModel());}}
